<?php class DashboardModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;}function contar($tabla){$permitidas=['estudiantes','profesores','cursos','inscripciones','tutorias'];if(!in_array($tabla,$permitidas,true))return 0;return (int)$this->pdo->query("SELECT COUNT(*) FROM {$tabla}")->fetchColumn();}function promedioNotas(){return (float)$this->pdo->query('SELECT COALESCE(AVG(nota),0) FROM calificaciones')->fetchColumn();}function porcentajeAsistencia(){return (float)$this->pdo->query("SELECT COALESCE(100*SUM(estado='presente')/NULLIF(COUNT(*),0),0) FROM asistencia")->fetchColumn();}function estadisticasEstudiante($idUsuario){$s=$this->pdo->prepare('SELECT id_estudiante FROM estudiantes WHERE id_usuario=?');$s->execute([$idUsuario]);$e=(int)$s->fetchColumn();$q=function($sql) use($e){$st=$this->pdo->prepare($sql);$st->execute([$e]);return $st->fetchColumn();};return ['cursos'=>(int)$q("SELECT COUNT(*) FROM inscripciones WHERE id_estudiante=? AND estado='activa'"),'tutorias'=>(int)$q('SELECT COUNT(*) FROM tutorias WHERE id_estudiante=?'),'realizadas'=>(int)$q("SELECT COUNT(*) FROM tutorias WHERE id_estudiante=? AND estado='realizada'"),'promedio'=>(float)$q('SELECT COALESCE(AVG(c.nota),0) FROM calificaciones c JOIN inscripciones i ON i.id_inscripcion=c.id_inscripcion WHERE i.id_estudiante=?'),'asistencia'=>(float)$q("SELECT COALESCE(100*SUM(a.estado='presente')/NULLIF(COUNT(*),0),0) FROM asistencia a JOIN inscripciones i ON i.id_inscripcion=a.id_inscripcion WHERE i.id_estudiante=?")];}function notasPorCurso(){return $this->pdo->query("SELECT c.codigo,c.nombre_curso,ROUND(COALESCE(AVG(cal.nota),0),1) promedio FROM cursos c LEFT JOIN inscripciones i ON i.id_curso=c.id_curso LEFT JOIN calificaciones cal ON cal.id_inscripcion=i.id_inscripcion GROUP BY c.id_curso ORDER BY c.codigo")->fetchAll();}}
